options.customCss:
:root {
    /* ================================
       AI COMPLAINT MANAGEMENT SYSTEM
       Professional Government Portal
       ================================ */

    /* Typography */
    --font-family: 'Inter', 'Open Sans', Arial, sans-serif;

    --font-weight-normal: 400;
    --font-weight-medium: 500;
    --font-weight-semibold: 600;
    --font-weight-bold: 700;

    --font-size-body: 13px;
    --font-size-label: 14px;
    --font-size-test-notice: 12px;
    --font-size-input: 14px;
    --font-size-header: 24px;
    --font-size-paragraph: 14px;
    --font-size-link: 13px;
    --font-size-error: 12px;

    --font-size-html-h1: 32px;
    --font-size-html-h2: 24px;
    --font-size-html-h3: 18px;
    --font-size-html-h4: 16px;
    --font-size-html-h5: 14px;
    --font-size-html-h6: 12px;
    --font-size-subheader: 14px;


    /* ================================
       PROFESSIONAL COLOR SYSTEM
       ================================ */

    /* Main Background */
    --color-background: #f4f7fb;

    /* Card */
    --color-card-bg: #ffffff;
    --color-card-border: #e2e8f0;
    --color-card-shadow: rgba(15, 23, 42, 0.08);

    /* Primary Navy */
    --color-primary: #0f2747;
    --color-primary-dark: #091b33;
    --color-primary-light: #eaf2fb;

    /* Professional Blue */
    --color-accent: #1769aa;
    --color-accent-dark: #0f568d;
    --color-accent-light: #e8f3fc;

    /* Text */
    --color-header: #172033;
    --color-html-text: #334155;
    --color-label: #344054;
    --color-input-text: #1f2937;
    --color-header-subtext: #64748b;

    /* Links */
    --color-link: #1769aa;
    --color-html-link: #1769aa;

    /* Inputs */
    --color-input-border: #cbd5e1;
    --color-input-background: #ffffff;
    --color-focus-border: #1769aa;
    --color-focus-shadow: rgba(23, 105, 170, 0.15);

    /* Submit Button */
    --color-submit-btn-bg: #1769aa;
    --color-submit-btn-hover: #0f568d;
    --color-submit-btn-text: #ffffff;

    /* Status Colors */
    --color-success: #16803c;
    --color-success-bg: #eaf7ef;

    --color-warning: #b7791f;
    --color-warning-bg: #fff8e6;

    --color-danger: #c53030;
    --color-danger-bg: #fff1f1;

    --color-info: #1769aa;
    --color-info-bg: #e8f3fc;

    /* Errors */
    --color-error: #d92d20;
    --color-required: #d92d20;

    /* Test Notice */
    --color-test-notice-text: #8a5a00;
    --color-test-notice-bg: #fff8e6;
    --color-test-notice-border: #f3d38a;

    /* Clear Button */
    --color-clear-button-bg: #64748b;
    --color-clear-button-hover: #475569;


    /* ================================
       BORDER RADIUS
       ================================ */

    --border-radius-card: 12px;
    --border-radius-input: 8px;
    --border-radius-button: 8px;
    --border-radius-clear-btn: 50%;

    --card-border-radius: 12px;


    /* ================================
       SPACING
       ================================ */

    --padding-container-top: 32px;

    --padding-card: 30px;
    --card-padding: 30px;

    --padding-form-input: 13px;

    --padding-test-notice-vertical: 12px;
    --padding-test-notice-horizontal: 20px;

    --margin-bottom-card: 20px;
    --card-margin-bottom: 20px;


    /* ================================
       DIMENSIONS
       ================================ */

    --container-width: 620px;

    --submit-btn-height: 50px;

    --checkbox-size: 18px;


    /* ================================
       SHADOWS
       ================================ */

    --box-shadow-card:
        0 10px 30px rgba(15, 23, 42, 0.07);

    --box-shadow-input:
        0 1px 3px rgba(15, 23, 42, 0.04);

    --box-shadow-button:
        0 4px 12px rgba(23, 105, 170, 0.20);


    /* ================================
       PLACEHOLDER
       ================================ */

    --opacity-placeholder: 0.55;
}

parameters.jsCode:
const year = new Date().getFullYear();

const randomNumber = Math.floor(10000 + Math.random() * 90000);

const complaintId = `CMP-${year}-${randomNumber}`;

return [
  {
    json: {
      ...$json,
      complaint_id: complaintId,
      created_at: new Date().toISOString(),
      status: "AI Analysis in Progress"
    }
  }
];

